1	package loja.checkout;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	import java.util.Map;
6	import loja.checkout.clube.NivelClube;
7	import loja.checkout.cupom.Cupom;
8	import loja.checkout.entrega.Entrega;
