11	import org.springframework.stereotype.Service;
12	
13	@Service
14	public class ResumoService {
15	    private final Map<String, Entrega> entregas;
16	    private final Map<String, Cupom> cupons;
17	    private final Map<String, NivelClube> niveis;
18	    private final Map<String, FormaPagamento> pagamentos;
19	
20	    public ResumoService(List<Entrega> entregas, List<Cupom> cupons, List<NivelClube> niveis,
21	                         List<FormaPagamento> pagamentos) {
22	        this.entregas = Codificado.indexar(entregas);
23	        this.cupons = Codificado.indexar(cupons);
24	        this.niveis = Codificado.indexar(niveis);
25	        this.pagamentos = Codificado.indexar(pagamentos);
26	    }
27	
28	    public ResumoResponse calcular(PedidoRequest pedido) {
29	        Carrinho carrinho = carrinho(pedido);
30	        NivelClube nivel = escolher(niveis, pedido.nivelClube(), "NIVEL_CLUBE_INVALIDO");
31	        Regiao regiao = regiao(pedido.regiao());
32	        Entrega entrega = escolher(entregas, pedido.modalidadeEntrega(), "MODALIDADE_INVALIDA");
33	        if (!entrega.atende(carrinho)) {
34	            throw new ErroNegocio("MODALIDADE_INDISPONIVEL");
35	        }
36	
37	        BigDecimal subtotal = carrinho.subtotal();
38	        BigDecimal frete = nivel.freteCobrado(entrega.frete(carrinho));
39	        BigDecimal desconto = descontoCupom(pedido.cupom(), carrinho, frete);
40	        BigDecimal seguro = regiao.seguro(subtotal);
41	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
42	
43	        FormaPagamento pagamento = escolher(pagamentos, pedido.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
44	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
45	        if (!pagamento.parcelasPermitidas(parcelas)) {
46	            throw new ErroNegocio("PARCELAMENTO_INVALIDO");
47	        }
48	        if (!pagamento.disponivel(totalPedido)) {
49	            throw new ErroNegocio("FORMA_PAGAMENTO_INDISPONIVEL");
50	        }
51	        Cobranca cobranca = pagamento.cobrar(totalPedido, parcelas);
52	
53	        return new ResumoResponse(subtotal, desconto, frete, entrega.prazoDias(), seguro,
54	                Dinheiro.arredondar(cobranca.totalFinal().subtract(totalPedido)),
55	                Dinheiro.arredondar(cobranca.totalFinal()), parcelas, cobranca.valorParcela(),
56	                nivel.credito(subtotal), nivel.brinde(subtotal));
57	    }
58	
59	    private BigDecimal descontoCupom(String codigo, Carrinho carrinho, BigDecimal frete) {
60	        if (codigo == null) {
61	            return Dinheiro.ZERO;
62	        }
63	        Cupom cupom = escolher(cupons, codigo, "CUPOM_INVALIDO");
64	        if (!cupom.aplicavel(carrinho)) {
65	            throw new ErroNegocio("CUPOM_NAO_APLICAVEL");
66	        }
67	        return cupom.desconto(carrinho, frete);
68	    }
69	
70	    private static <T> T escolher(Map<String, T> opcoes, String codigo, String erro) {
71	        T opcao = codigo == null ? null : opcoes.get(codigo);
72	        if (opcao == null) {
73	            throw new ErroNegocio(erro);
74	        }
75	        return opcao;
76	    }
77	
78	    private static Regiao regiao(String codigo) {
79	        try {
80	            return Regiao.valueOf(codigo);
81	        } catch (IllegalArgumentException | NullPointerException e) {
82	            throw new ErroNegocio("REGIAO_INVALIDA");
83	        }
84	    }
85	
86	    private static Carrinho carrinho(PedidoRequest pedido) {
87	        if (pedido.itens() == null || pedido.itens().isEmpty()) {
88	            throw new ErroNegocio("PEDIDO_INVALIDO");
89	        }
90	        List<Item> itens = pedido.itens().stream().map(i -> {
91	            if (i == null || i.precoUnitario() == null || i.quantidade() == null || i.pesoKg() == null
92	                    || i.precoUnitario().signum() <= 0 || i.quantidade() <= 0 || i.pesoKg().signum() <= 0) {
93	                throw new ErroNegocio("PEDIDO_INVALIDO");
94	            }
95	            return new Item(i.nome(), i.precoUnitario(), i.quantidade(), i.pesoKg());
96	        }).toList();
97	        return new Carrinho(itens);
98	    }
99	}
