4	import java.math.MathContext;
5	import loja.checkout.Dinheiro;
6	import org.springframework.stereotype.Component;
7	
8	@Component
9	public class Cartao implements FormaPagamento {
10	    private static final int MAXIMO_PARCELAS = 12;
11	    private static final int MAXIMO_SEM_JUROS = 3;
12	    private static final BigDecimal TAXA = new BigDecimal("0.0199");
13	
14	    @Override
15	    public String codigo() {
16	        return "CARTAO";
17	    }
18	
19	    @Override
20	    public boolean parcelasPermitidas(int parcelas) {
21	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
22	    }
23	
24	    @Override
25	    public boolean disponivel(BigDecimal totalPedido) {
26	        return true;
27	    }
28	
29	    @Override
30	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
31	        if (parcelas <= MAXIMO_SEM_JUROS) {
32	            return new Cobranca(totalPedido, Dinheiro.arredondar(totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128)));
33	        }
34	        BigDecimal fator = BigDecimal.ONE.add(TAXA).pow(parcelas);
35	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, MathContext.DECIMAL128));
36	        BigDecimal parcela = Dinheiro.arredondar(totalPedido.multiply(TAXA).divide(divisor, MathContext.DECIMAL128));
37	        return new Cobranca(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela);
38	    }
39	}
